#include "numerics.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace hour_local;
int main(int argc,char**argv){try{std::filesystem::path out=argc>1?argv[1]:"results";std::filesystem::create_directories(out);std::ofstream csv(out/"branch_comparison.csv"),refine(out/"reference_checks.csv");csv<<std::setprecision(16)<<"case,scenario,phase,h,method,converged,reference_converged,primal,stationarity,objective_gap,scaled_state_difference,reduced_curvature,reference_curvature,evaluations,reason\n";refine<<std::setprecision(16)<<"case,scenario,phase,h,position_refinement,velocity_refinement,relative_energy_refinement\n";
 std::ofstream large(out/"large_validation.csv");large<<std::setprecision(16)<<"N,check,objective_gradient_error,objective_hessian_error,constraint_gradient_error,constraint_hessian_error,passed\n";
 for(int N:{8,32}){auto c=chain_case(N,1,10);double E=energy(c.model,c.initial)-minimum_energy(c.model);Problem p(c.model,c.initial,1./60,E);V z=p.initial();for(int i=0;i<z.size();++i)z[i]+=.001*std::sin(i+1.);auto e=p.evaluate(z);double fg=0,fh=0,cg=0,ch=0;
   if(N==8){auto a=p.oracle(z);fg=(e.objective.g-a.objective.g).cwiseAbs().maxCoeff();fh=(e.objective.H-a.objective.H).cwiseAbs().maxCoeff();cg=(jacobian(e)-jacobian(a)).cwiseAbs().maxCoeff();for(int i=0;i<int(e.rows.size());++i)ch=std::max(ch,(e.rows[i].value.H-a.rows[i].value.H).cwiseAbs().maxCoeff());}
   else{V d(z.size());for(int i=0;i<d.size();++i)d[i]=std::sin(.7*i+.3);d.normalize();double eps=1e-6;auto a=p.evaluate(z+eps*d),b=p.evaluate(z-eps*d);fg=std::abs((a.objective.a-b.objective.a)/(2*eps)-e.objective.g.dot(d));fh=((a.objective.g-b.objective.g)/(2*eps)-e.objective.H*d).cwiseAbs().maxCoeff();cg=((residuals(a)-residuals(b))/(2*eps)-jacobian(e)*d).cwiseAbs().maxCoeff();for(int i=0;i<int(e.rows.size());++i)ch=std::max(ch,((a.rows[i].value.g-b.rows[i].value.g)/(2*eps)-e.rows[i].value.H*d).cwiseAbs().maxCoeff());}
   bool pass=std::max({fg,fh,cg,ch})<1e-6;large<<N<<','<<(N==8?"AD":"directional_finite_difference")<<','<<fg<<','<<fh<<','<<cg<<','<<ch<<','<<pass<<'\n';if(!pass)throw std::runtime_error("large_derivative_check_failed");}
 for(std::string name:{"scalar_release","radial_orbit","rod_kick","elastic_mixed","chain_mixed"})for(std::string scenario:{"nominal","stiff10"}){if(name=="rod_kick"&&scenario!="nominal")continue;auto c=make_case(name,scenario=="stiff10"?10:1);double E=std::max(1e-8,energy(c.model,c.initial)-minimum_energy(c.model));for(double phase:{0.,.3,.65}){State old=phase?reference_step(c.model,c.initial,phase,2048):c.initial;for(double h:{1./60,1./30}){auto a=reference_step(c.model,old,h,64),b=reference_step(c.model,old,h,128);if((a.x-b.x).norm()>1e-7||(a.v-b.v).norm()>1e-6||std::abs(energy(c.model,a)-energy(c.model,b))/E>1e-8)throw std::runtime_error("reference_refinement_failed");refine<<name<<','<<scenario<<','<<phase<<','<<h<<','<<(a.x-b.x).norm()<<','<<(a.v-b.v).norm()<<','<<std::abs(energy(c.model,a)-energy(c.model,b))/E<<'\n';Problem p(c.model,old,h,E);Options o;o.budget=512;auto reference=solve(p,o);double refcurv=reference.converged?reduced_curvature(p,reference):0;if(!reference.converged||refcurv<-1e-7)throw std::runtime_error("joint_reference_not_checked_minimum");for(auto option:small_options()){if(option.warm)continue;auto r=solve(p,option);csv<<name<<','<<scenario<<','<<phase<<','<<h<<','<<option.id<<','<<r.converged<<','<<reference.converged<<','<<r.primal<<','<<r.dual_residual<<','<<r.objective-reference.objective<<','<<(r.z-reference.z).norm()<<','<<(r.converged?reduced_curvature(p,r):0)<<','<<refcurv<<','<<r.evaluations<<','<<r.reason<<'\n';}}}}
 for(int N:{2,8,32})for(std::string scenario:{"nominal","stiff10","mass10"}){auto c=chain_case(N,scenario=="stiff10"?10:1,scenario=="mass10"?10:1);double E=energy(c.model,c.initial)-minimum_energy(c.model);auto a=reference_step(c.model,c.initial,1./60,64),b=reference_step(c.model,c.initial,1./60,128);if((a.x-b.x).norm()>1e-7||(a.v-b.v).norm()>1e-6||std::abs(energy(c.model,a)-energy(c.model,b))/E>1e-8)throw std::runtime_error("large_reference_refinement_failed");refine<<c.name<<','<<scenario<<",0,"<<1./60<<','<<(a.x-b.x).norm()<<','<<(a.v-b.v).norm()<<','<<std::abs(energy(c.model,a)-energy(c.model,b))/E<<'\n';}
 std::cout<<"branch and reference audits complete\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
